```python
from datetime import datetime


def parse_to_iso(date_str: str) -> str:
    formats = ["%d/%m/%Y", "%m/%d/%Y", "%B %d, %Y", "%Y-%m-%d", "%d %b %Y"]

    for fmt in formats:
        try:
            dt = datetime.strptime(date_str, fmt)
            return dt.date().isoformat()
        except ValueError:
            continue

    raise ValueError(f"Date string '{date_str}' did not match any known format.")


