    date_samples = [
        "12/03/2024",
        "March 5, 2021",
        "2019-07-04",
        "1 Jan 2000",
        "31/12/1999",
    ]

    for sample in date_samples:
        print(parse_to_iso(sample))


if __name__ == "__main__":
    main()
