I will use Python's built-in `datetime` module from the standard library to parse the date strings without relying on external dependencies. Candidate format strings will be attempted sequentially for each input until parsing succeeds without a `ValueError`. Once parsed, each date will be printed in ISO format (`YYYY-MM-DD`) using `.strftime('%Y-%m-%d')` or `.isoformat()`.

```python
from datetime import datetime


def parse_to_iso(date_str: str) -> str:
    formats = [
        "%d/%m/%Y",  # e.g., "12/03/2024", "31/12/1999"
        "%m/%d/%Y",  # alternative numeric format
        "%B %d, %Y",  # e.g., "March 5, 2021"
        "%Y-%m-%d",  # e.g., "2019-07-04"
        "%d %b %Y",  # e.g., "1 Jan 2000"
        "%d %B %Y",  # full month name variant
    ]

    for fmt in formats:
        try:
            dt = datetime.strptime(date_str, fmt)
            return dt.date().isoformat()
        except ValueError:
            continue

    raise ValueError(f"Date string '{date_str}' does not match any known format.")


def main():
    date_samples = [
        "12/03/2024",
        "March 5, 2021",
        "2019-07-04",
        "1 Jan 2000",
        "31/12/1999",
    ]

    for sample in date_samples:
        print(parse_to_iso(sample))


if __name__ == "__main__":
    main()
